For a general pseudoeffective class on a compact K\"ahler manifold, the appropriate replacement is the numerical restricted volume of Collins--Tosatti \cite[Section 2]{CT22Restricted}. For an irreducible compact analytic subvariety $V\subset X$ of dimension $k>0$, let $V_{\mathrm{reg}}$ be its regular locus. The numerical restricted volume is zero when $V\subset E_{\mathrm{nn}}(\alpha)$. Otherwise, for real $\varepsilon>0$, let $T$ range over closed representatives of $\alpha$ with $T\geq-\varepsilon\omega$, analytic singularities with smooth remainder, and polar set not containing $V$. The subscript $\mathrm{ac}$ denotes the absolutely continuous part on $V_{\mathrm{reg}}$. The volume is
\begin{equation}\label{eq:bc-numerical-restricted-volume}
 \langle\alpha^k\rangle_{X\mid V}
 =\lim_{\varepsilon\downarrow0}\ \sup_T
 \int_{V_{\mathrm{reg}}}
      \bigl((T+\varepsilon\omega)|_{V_{\mathrm{reg}}}\bigr)_{\mathrm{ac}}^k.
\end{equation}
The condition that the analytic singularities have a \emph{smooth} remainder makes the displayed measure the extension by zero of a smooth measure away from an analytic subset. It must not be replaced without explanation by the weaker condition of a bounded remainder.

\begin{theorem}[Guedj--Lu]\label{thm:semipositive-bounded-domination}
Let $\theta\geq0$ be non-collapsing on bounded potentials. Suppose $u,v\in\PSH(X,\theta)\cap L^\infty(X)$ and $0\leq c<1$. If
\[
 \mathbf1_{\{u<v\}}\mathrm{MA}_\theta(u)
 \leq c\,\mathbf1_{\{u<v\}}\mathrm{MA}_\theta(v),
\]
then $u\geq v$.
\end{theorem}
\begin{proof}
We give the envelope argument of \cite[Proposition 2.8]{GL22}. If the conclusion failed, choose $a>0$ such that $E=\{u<v-a\}$ is nonempty. This set has positive volume by \cref{lem:strict-set-positive-volume}. Fix $C$ with $|u|,|v|\leq C$.

\begin{lemma}\label{lem:kahler-modification-bounded-mass}
If a compact complex manifold $X$ admits a modification $\pi:Z\to X$ from a compact K\"ahler manifold, then $X$ has the bounded mass property.
\end{lemma}
\begin{proof}
Fix a Hermitian form $\omega$ on $X$ and a K\"ahler form $\kappa$ on $Z$. Choose $C>0$ with $\pi^*\omega\leq C\kappa$. For any bounded $u\in\PSH(X,\omega)$, its pullback is bounded and satisfies
\[
 0\leq\pi^*\omega+\ddc(u\circ\pi)
 \leq C\kappa+\ddc(u\circ\pi).
\]
The two bounded positive products give
\[
 \begin{split}
 \int_X(\omega+\ddc u)^n
 &=\int_Z(\pi^*\omega+\ddc(u\circ\pi))^n\\
 &\leq\int_Z(C\kappa+\ddc(u\circ\pi))^n
 =C^n\int_Z\kappa^n.
 \end{split}
\]
The first equality follows on the biholomorphic locus by the local Bedford--Taylor change of variables; both measures assign zero mass to the excluded analytic sets, so it holds globally. The inequality is positivity of mixed products. The last equality is bounded Bedford--Taylor Stokes in the closed K\"ahler background, or the usual bounded mass identity recalled in \cite{SGPT}. The right side is independent of $u$, proving bounded mass. This is also the upper-volume pullback argument of \cite[Lemma 3.6]{GL22}.
\end{proof}

For a big, possibly non-semipositive form under bounded mass, Li uses
\begin{equation}\label{eq:li-model-condition}
 P_\theta[\varphi]=\varphi,\qquad
 \underline{\operatorname{vol}}_\theta(\varphi)>0.
\end{equation}
Under bounded mass, positive lower volume implies the smaller-background condition by \cite[Proposition 2.11]{ALS26}. In the latter assertion $\theta$ is semipositive and big, and the reference is an ordinary envelope fixed point. The smaller-background condition \eqref{eq:als-model-condition} does not itself assert a uniform positive lower mass. Its no-mass-bound consequences were proved in \cref{sec:relative-envelope-room}.

First, \cref{thm:normalized-compactness} gives, for normalized potentials $v\in\PSH(X,\omega)$ with $\sup_Xv=0$,
\begin{equation}\label{eq:normalized-lone}
 \int_X|v|\,\mathrm{d}V\leq K_\omega.
\end{equation}
Changing the smooth volume form only changes the constant. The genuine decreasing-limit consequence is \cref{cor:decreasing-limit}. The normalized estimate is also recorded in \cite[Proposition 6.2]{Dinew16}.

Apply the classical regularization theorem \cite[Theorem 4.1]{Dem94} to the closed current $\ddc p$ and its smooth lower bound $-\theta$. This theorem applies to a quasi-plurisubharmonic potential with finite $L^1$ norm, including an unbounded one. Choose its fixed Chern-connection averaging operators $R_t$, at radius $t>0$, and constants $A,K>0$ as in the proof of \cref{lem:general-kiselman-modulus}. The absorption of the mixed and vertical errors in that proof does not use semipositivity of $\theta$ or boundedness of the potential. For $c>0$ and sufficiently small $\delta>0$, it gives an increasing error function $\epsilon(\delta)\geq0$ tending to zero and the transform
\[
 \Phi_{c,\delta}
   =\inf_{0<t\leq\delta}
       \{R_tp+K(t^2-\delta^2)+K(t-\delta)-c\log(t/\delta)\}
\]
on $X\setminus Z$, with
\begin{equation}\label{eq:big-envelope-regularization}
 \theta+\ddc\Phi_{c,\delta}
             \geq-(Ac+\epsilon(\delta))\omega.
\end{equation}
Here is why the minimum argument remains valid. On a fixed compact neighborhood off $Z$, $p$ has a uniform lower bound, and $R_tp+Kt^2\geq p$. Thus the logarithmic penalty excludes radii near zero uniformly on that neighborhood. The radius localization, strict logarithmic convexity, and minimum principle in the cited proof apply unchanged there. This proves the current inequality locally everywhere off $Z$. Evaluation at the cap gives the global upper bound
\[
 \Phi_{c,\delta}\leq R_\delta p\leq R_\delta h.
\]
In particular the transform is bounded above near $Z$.

\Needspace{14\baselineskip}
\begin{lemma}\label{lem:nonclosed-mixed-density}
Let $\theta$ be any smooth real background, and let $u,v$ be bounded $\theta$-plurisubharmonic functions. For nonnegative measurable functions $f,g$ on $X$, suppose
\[
 \theta_u^n\geq f\,\mathrm{d}V,\qquad\theta_v^n\geq g\,\mathrm{d}V,
 \qquad f,g\geq0,
\]
then
\[
 \theta_u^k\wedge\theta_v^{n-k}
 \geq f^{k/n}g^{(n-k)/n}\,\mathrm{d}V,\qquad0\leq k\leq n.
\]
\end{lemma}
\begin{proof}
The standard local mixed Monge--Amp\`ere inequality for bounded plurisubharmonic functions is the input here; it concerns ordinary closed local Hessians and measurable smooth-volume densities, as stated in \cite[Theorem 1.2]{Dinew09}. We explain why no closedness of $\theta$ is required in its present use.

Let $E=\mathbb C/(\mathbb Z+i\mathbb Z)$, let $\omega_E=(i/2\pi)\,\mathrm{d}z\wedge\mathrm{d}\bar z$, and put $X=E^n$, $D=\{0\}\times E^{n-1}$ and $M=X\setminus D$. Write $\pi_j:X\to E$ for the coordinate projections and $\omega_0=\sum_{j=1}^n\pi_j^*\omega_E$. For a smooth background $\theta$ and a $\theta$-plurisubharmonic potential $u$, use $\mathrm{MA}_\theta(u)$ for the extended non-pluripolar measure of \cref{thm:arbitrary-extended-ma}. Lengths use the metric $g_T$ normalized above. Choose radii $0<r_1<r_2<\mathrm{e}^{-1}$ and a smooth radial cutoff $\chi$ on the coordinate disc $\{|z|<r_2\}\subset E$, equal to $1$ on $\{|z|\leq r_1\}$ and to $0$ near its outer boundary, with $0\leq\chi\leq1$. For fixed numbers $A,\eta,\beta>0$, set $L=-\log|z|^2$ and define on $E$
\begin{equation}\label{eq:torus-length-profiles}
 v_{\mathrm c}=-A\chi\log L,\qquad
 v_\beta=\eta\chi L^{-\beta}.
\end{equation}
Both functions are extended by zero outside the disc; at its center set $v_{\mathrm c}(0)=-\infty$ and $v_\beta(0)=0$. These are the profiles of \cite[Lemma~3.1 and Propositions~3.2--3.3]{SuppliedCompleteness26}. The bounded profile also occurs in \cref{ex:logarithmic-continuous-density}. We verify their global mass and metric properties directly.

Write $\mathrm{d}V=J\,\mathrm{d}\Lambda$ in these coordinates, where $\mathrm{d}\Lambda$ is Euclidean volume, and set $G=\pi^n fJ/n!$. Our normalization gives
\begin{equation}\label{eq:local-density-determinant}
 (\ddc V)^n=\frac{n!}{\pi^n}\det(V_{j\bar k})\,\mathrm{d}\Lambda
\end{equation}
for smooth $V$. There is a smooth strictly plurisubharmonic $V$ on $\overline B$ with determinant $G$ and boundary value $\varphi$. For $n\geq2$, this is the classical Dirichlet input \cite[Theorem~1.1, p.~1186]{GL10}, applied with zero background and flat Hermitian metric. Indeed, if $\Phi$ smoothly extends $\varphi$, then $\Phi+A(|z-z_0|^2-R^2)$ is a strict subsolution when $A$ is sufficiently large. Here the cited equation has background zero, metric $(\mathrm{i}/2)\partial\bar\partial|z|^2$, and right-hand side $G$. For $n=1$, extend $G$ smoothly with compact support and convolve with $\pi^{-1}\log|z|^2$; adding the harmonic extension of the remaining smooth boundary values gives $V$.

\Needspace{12\baselineskip}
\begin{lemma}\label{lem:moving-bounded-integrals}
Let $a_j,a,w_j,w\in\PSH(X,\omega)$ be uniformly bounded. If $a_j\to a$ in $L^1(X)$ and $w_j\to w$ in capacity, then, for $0\leq k\leq n$,
\[
 \int_X|a_j-a|\,\omega_{w_j}^{k}\wedge\omega^{n-k}
 \longrightarrow0.
\]
The same conclusion holds when the $a_j$ have any fixed smooth lower curvature bound.
\end{lemma}
\begin{proof}
We give the torsion calculation behind \cite[Lemma 2.3]{KN22}. By the subsequence criterion, we may first extract $a_j\to a$ almost everywhere for smooth volume. The upper tail envelopes
$A_j=(\sup_{\ell\geq j}a_\ell)^*$ decrease to $a$: the local Hartogs lemma gives the upper inequality for the limit, and almost-everywhere convergence gives the reverse one. Bounded monotone capacity convergence therefore implies
\[
 \alpha_j:=\max(a_j,a)\longrightarrow a\quad\text{in capacity}.
\]
The part $\alpha_j-a$ of $|a_j-a|=(\alpha_j-a)+(\alpha_j-a_j)$ tends to zero against the moving products by \cref{lem:bounded-mixed-capacity}.
